      case StoreSearch.FriendlyName friendlyName:
      {
        writer.WriteString("FriendlyName",
                           friendlyName.Value);
        break;
      }
    }

    writer.WriteEndObject();
  }
}

/// <summary>The certificate the client presents, and its key.</summary>
[JsonConverter(typeof(ClientCertificateJsonConverter))]
public abstract record ClientCertificate
{
  private ClientCertificate()
  {
  }

  /// <summary>From PEM files.</summary>
  /// <param name="Certificate">Path to a PEM file of the client's certificate, then each issuer the server may not hold.</param>
  /// <param name="Key">Path to a PEM file of the certificate's key.</param>
  public sealed record Pem(string Certificate,
                           string Key) : ClientCertificate
  {
    /// <summary>Path to a PEM file of the client's certificate, then each issuer the server may not hold.</summary>
    public string Certificate { get; init; } = Certificate ?? throw new ArgumentNullException(nameof(Certificate));

    /// <summary>Path to a PEM file of the certificate's key.</summary>
    public string Key { get; init; } = Key ?? throw new ArgumentNullException(nameof(Key));

    /// <inheritdoc />
    public override void Validate()
    {
      if (Certificate is string certificate && certificate.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Certificate),
                                              certificate,
                                              "Certificate has to be at least 1 character long.");
      }

      if (Key is string key && key.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Key),
                                              key,
                                              "Key has to be at least 1 character long.");
      }
    }
  }

  /// <summary>From a PKCS#12 bundle.</summary>
  /// <param name="Path">Path to a PKCS#12 bundle of the client's certificate, the issuers it carries and the key.</param>
  /// <param name="Password">
  ///   The password the bundle is protected by.
  ///   Defaults to the empty one. Taken from the runtime's channel defaults only when they name
  ///   the same <c>Path</c>.
  /// </param>
  public sealed record P12(string Path,
                           string? Password = null) : ClientCertificate
  {
    /// <summary>Path to a PKCS#12 bundle of the client's certificate, the issuers it carries and the key.</summary>
    public string Path { get; init; } = Path ?? throw new ArgumentNullException(nameof(Path));

    /// <inheritdoc />
    public override void Validate()
    {
      if (Path is string path && path.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Path),
                                              path,
                                              "Path has to be at least 1 character long.");
      }
    }

    /// <summary>The fields, a secret one elided.</summary>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
      builder.Append("Path = ");
      builder.Append((object?)Path);
      builder.Append(", Password = ");
      builder.Append(Password is null ? "null" : "***");

      return true;
    }
  }

  /// <summary>
  ///   From a Windows certificate store, <c>My</c> unless <c>Name</c> says otherwise, with the issuers the
  ///   store's <c>CA</c> holds. Its key has to be exportable.
  /// </summary>
  /// <remarks>Refused off Windows.</remarks>
  /// <param name="Find">How the certificate is found in the store.</param>
  /// <param name="Location">
  ///   Where the store is.
  ///   Defaults to <c>CurrentUser</c>.
  /// </param>
  /// <param name="Name">The store's name, such as <c>My</c>, <c>Root</c> or <c>CA</c>. Defaults to the one its option states.</param>
  public sealed record Store(StoreSearch Find,
                             StoreLocation? Location = null,
                             string? Name = null) : ClientCertificate
  {
    /// <summary>How the certificate is found in the store.</summary>
    public StoreSearch Find { get; init; } = Find ?? throw new ArgumentNullException(nameof(Find));

    /// <inheritdoc />
    public override void Validate()
    {
      if (Location is StoreLocation location && !Enum.IsDefined(typeof(StoreLocation), location))
      {
        throw new ArgumentOutOfRangeException(nameof(Location),
                                              location,
                                              "Location has to be a name StoreLocation declares.");
      }

      if (Name is string name && name.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Name),
                                              name,
                                              "Name has to be at least 1 character long.");
      }

      Find.Validate();
    }
  }

  /// <summary>Refuses a field outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">A field is outside its stated bounds.</exception>
  public abstract void Validate();

  /// <summary>The alternative <paramref name="section" /> names by its one key, matched without case.</summary>
  /// <param name="section">The section, which has to hold one key.</param>
  /// <returns>The alternative, with the fields its key states.</returns>
  /// <exception cref="InvalidOperationException">
  ///   The section names no alternative or two, or one with a field it does not admit.
  /// </exception>
  internal static ClientCertificate Bind(IConfigurationSection section)
  {
    var alternative = ChannelOptionsConfiguration.Alternative(section,
                                                              "ClientCertificate");

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "Pem"))
    {
      string? certificate = null;
      string? key = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "Certificate"))
        {
          certificate = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Key"))
        {
          key = ChannelOptionsConfiguration.Text(entry);
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "ClientCertificate.Pem");
        }
      }

      return new Pem(certificate ?? throw ChannelOptionsConfiguration.Missing(alternative,
                                                                              "Certificate"),
                     key ?? throw ChannelOptionsConfiguration.Missing(alternative,
                                                                      "Key"));
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "P12"))
    {
      string? path = null;
      string? password = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "Path"))
        {
          path = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Password"))
        {
          password = ChannelOptionsConfiguration.Text(entry);
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "ClientCertificate.P12");
        }
      }

      return new P12(path ?? throw ChannelOptionsConfiguration.Missing(alternative,
                                                                       "Path"),
                     password);
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "Store"))
    {
      StoreSearch? find = null;
      StoreLocation? location = null;
      string? name = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "Location"))
        {
          location = ChannelOptionsConfiguration.Enumeration<StoreLocation>(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Name"))
        {
          name = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Find"))
        {
          find = ChannelOptionsConfiguration.Holds(entry) ? StoreSearch.Bind(entry) : null;
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "ClientCertificate.Store");
        }
      }

      return new Store(find ?? throw ChannelOptionsConfiguration.Missing(alternative,
                                                                         "Find"),
                       location,
                       name);
    }

    throw ChannelOptionsConfiguration.Unknown(alternative,
                                              "ClientCertificate");
  }
}

/// <summary>Writes a <see cref="ClientCertificate" /> as the engine reads one: an object whose one key names the alternative.</summary>
internal sealed class ClientCertificateJsonConverter : JsonConverter<ClientCertificate>
{
  /// <inheritdoc />
  /// <remarks>Options go to the engine and nothing reads them back, so this reads nothing.</remarks>
  public override ClientCertificate? Read(ref Utf8JsonReader reader,
                                          Type typeToConvert,
                                          JsonSerializerOptions options)
    => throw new NotSupportedException("ClientCertificate is written to the engine, and never read back.");

  /// <inheritdoc />
  public override void Write(Utf8JsonWriter writer,
                             ClientCertificate value,
                             JsonSerializerOptions options)
    => WriteValue(writer,
                  value);

  /// <summary>Writes <paramref name="written" />, as the converter of a choice holding one does too.</summary>
  /// <param name="writer">Where it is written.</param>
  /// <param name="written">The alternative.</param>
  internal static void WriteValue(Utf8JsonWriter writer,
                                  ClientCertificate written)
  {
    writer.WriteStartObject();

    switch (written)
    {
      case ClientCertificate.Pem pem:
      {
        writer.WriteStartObject("Pem");
        writer.WriteString("Certificate",
                           pem.Certificate);
        writer.WriteString("Key",
                           pem.Key);
        writer.WriteEndObject();
        break;
      }

      case ClientCertificate.P12 p12:
      {
        writer.WriteStartObject("P12");
        writer.WriteString("Path",
                           p12.Path);

        if (p12.Password is string password)
        {
          writer.WriteString("Password",
                             password);
        }

        writer.WriteEndObject();
        break;
      }

      case ClientCertificate.Store store:
      {
        writer.WriteStartObject("Store");

        if (store.Location is StoreLocation location)
        {
          writer.WriteString("Location",
                             location.ToString());
        }

        if (store.Name is string name)
        {
          writer.WriteString("Name",
                             name);
        }

        writer.WritePropertyName("Find");
        StoreSearchJsonConverter.WriteValue(writer,
                                            store.Find);
        writer.WriteEndObject();
        break;
      }
    }

    writer.WriteEndObject();
  }
}

/// <summary>The socket's keepalive, off unless <c>IdleSeconds</c> is set.</summary>
/// <remarks>Each duration is whole seconds, which is what the socket option holds: a fraction is dropped.</remarks>
public sealed class TcpKeepaliveOptions
{
  /// <summary>Options nobody has set.</summary>
  public TcpKeepaliveOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public TcpKeepaliveOptions(TcpKeepaliveOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    IdleSeconds = other.IdleSeconds;
    IntervalSeconds = other.IntervalSeconds;
    Retries = other.Retries;
  }

  /// <summary>
  ///   How long the connection may be idle before the first probe, from a second to 32767, the
  ///   most Linux holds.
  /// </summary>
  [JsonPropertyName("IdleSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? IdleSeconds { get; set; }

  /// <summary>How long between two probes, from a second to 32767. Defaults to the operating system's.</summary>
  /// <remarks>Refused without <c>IdleSeconds</c>.</remarks>
  [JsonPropertyName("IntervalSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? IntervalSeconds { get; set; }

  /// <summary>
  ///   How many probes go unanswered before the connection is dropped, at most 127, the most
  ///   Linux holds. Defaults to the operating system's, and is not applied on Windows.
  /// </summary>
  /// <remarks>Refused without <c>IdleSeconds</c>.</remarks>
  [JsonPropertyName("Retries")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Retries { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (IdleSeconds is double idleSeconds && (idleSeconds < 1 || idleSeconds > 32767 || idleSeconds >= 1.8446744073709552E+19 || double.IsNaN(idleSeconds) || double.IsInfinity(idleSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(IdleSeconds),
                                            idleSeconds,
                                            "IdleSeconds has to be at least 1 and at most 32767 and less than 1.8446744073709552E+19 and finite.");
    }

    if (IntervalSeconds is double intervalSeconds && (intervalSeconds < 1 || intervalSeconds > 32767 || intervalSeconds >= 1.8446744073709552E+19 || double.IsNaN(intervalSeconds) || double.IsInfinity(intervalSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(IntervalSeconds),
                                            intervalSeconds,
                                            "IntervalSeconds has to be at least 1 and at most 32767 and less than 1.8446744073709552E+19 and finite.");
    }

    if (Retries is int retries && (retries < 1 || retries > 127))
    {
      throw new ArgumentOutOfRangeException(nameof(Retries),
                                            retries,
                                            "Retries has to be at least 1 and at most 127.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static TcpKeepaliveOptions Bind(IConfigurationSection section)
  {
    var bound = new TcpKeepaliveOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "IdleSeconds"))
      {
        bound.IdleSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "IntervalSeconds"))
      {
        bound.IntervalSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Retries"))
      {
        bound.Retries = ChannelOptionsConfiguration.Int32(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "TcpKeepaliveOptions");
      }
    }

    return bound;
  }
}

/// <summary>
///   An HTTP proxy, which a dial tunnels through with <c>CONNECT</c>, so TLS stays end to end with the
///   server.
/// </summary>
[JsonConverter(typeof(ProxyOptionsJsonConverter))]
public abstract record ProxyOptions
{
  private ProxyOptions()
  {
  }

  /// <summary>No proxy: every dial goes to the endpoint itself.</summary>
  public sealed record None : ProxyOptions
  {
    /// <inheritdoc />
    public override void Validate()
    {
      // The schema bounds nothing here.
    }
  }

  /// <summary>The proxy the system names for the endpoint, if any.</summary>
  /// <remarks>
  ///   The environment's proxy is <c>ALL_PROXY</c>, <c>HTTPS_PROXY</c> or <c>HTTP_PROXY</c>, in either case and
  ///   by the endpoint's scheme, unless <c>NO_PROXY</c> names the endpoint's host; it is read when the
  ///   channel is created. An <c>https://</c> or <c>socks</c> one is refused when the channel is created,
  ///   and any other value the environment cannot read as a proxy is ignored.
  ///   On Windows, when the environment names no proxy, the system's is the one the current
  ///   user's network settings name: a PAC script, detected or at the configured address, which
  ///   WinHTTP fetches and runs for each dial off the calling thread, else the manual proxy and
  ///   its bypass list. Those settings are read when the channel is created, and an <c>https://</c> or
  ///   <c>socks</c> proxy they name is refused at each dial - except a script's <c>SOCKS</c> answer, which
  ///   WinHTTP drops, leaving a direct dial. A script that cannot be found or run is not tried
  ///   again for two minutes.
  ///   The system's proxy is never used for a loopback endpoint.
  /// </remarks>
  /// <param name="Username">
  ///   The username, which <c>Basic</c> forbids a <c>:</c> in.
  ///   Ignored when the system names no proxy. Beside the environment's proxy, it takes the place
  ///   of the username that proxy's URL carries; beside the one Windows' settings name, it is the
  ///   username. Taken from the runtime's channel defaults, with their <c>Password</c>, only when these
  ///   options state neither.
  /// </param>
  /// <param name="Password">
  ///   The password that goes with <c>Username</c>.
  ///   Ignored when the system names no proxy. Beside the environment's proxy, it takes the place
  ///   of the password that proxy's URL carries; beside the one Windows' settings name, it is the
  ///   password. Taken from the runtime's channel defaults, with their <c>Username</c>, only when these
  ///   options state neither.
  /// </param>
  public sealed record System(string? Username = null,
                              string? Password = null) : ProxyOptions
  {
    /// <inheritdoc />
    public override void Validate()
    {
      // The schema bounds nothing here.
    }

    /// <summary>The fields, a secret one elided.</summary>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
      builder.Append("Username = ");
      builder.Append((object?)Username);
      builder.Append(", Password = ");
      builder.Append(Password is null ? "null" : "***");

      return true;
    }
  }

  /// <summary>The proxy at an address that carries no credentials, with its own beside it, if any.</summary>
  /// <param name="Address">
  ///   The proxy's <c>http://</c> URL, with no path and no <c>user:password@</c>; <c>http://</c> is assumed when
  ///   no scheme is written.
  /// </param>
  /// <param name="Username">
  ///   The username the proxy is authenticated to with, by <c>Basic</c>, which forbids a <c>:</c> in it.
  ///   Taken from the runtime's channel defaults, with their <c>Password</c>, only when they name the
  ///   same <c>Address</c> and these options state neither.
  /// </param>
  /// <param name="Password">
  ///   The password that goes with <c>Username</c>.
  ///   Taken from the runtime's channel defaults, with their <c>Username</c>, only when they name the
  ///   same <c>Address</c> and these options state neither.
  /// </param>
  public sealed record Url(string Address,
                           string? Username = null,
                           string? Password = null) : ProxyOptions
  {
    /// <summary>
    ///   The proxy's <c>http://</c> URL, with no path and no <c>user:password@</c>; <c>http://</c> is assumed when
    ///   no scheme is written.
    /// </summary>
    public string Address { get; init; } = Address ?? throw new ArgumentNullException(nameof(Address));

    /// <inheritdoc />
    public override void Validate()
    {
      if (Address is string address && address.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Address),
                                              "Address has to be at least 1 character long.");
      }
    }

    /// <summary>The fields, a secret one elided.</summary>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
      builder.Append("Address = ");
      builder.Append(Address is null ? "null" : "***");
      builder.Append(", Username = ");
      builder.Append((object?)Username);
      builder.Append(", Password = ");
      builder.Append(Password is null ? "null" : "***");

      return true;
    }
  }

  /// <summary>
  ///   The proxy at an address that carries its credentials as <c>user:password@</c>, percent-encoded,
  ///   which a serialized document then carries too.
  /// </summary>
  /// <param name="Value">
  ///   The proxy at an address that carries its credentials as <c>user:password@</c>, percent-encoded,
  ///   which a serialized document then carries too.
  /// </param>
  public sealed record UrlWithCredentials(string Value) : ProxyOptions
  {
    /// <summary>
    ///   The proxy at an address that carries its credentials as <c>user:password@</c>, percent-encoded,
    ///   which a serialized document then carries too.
    /// </summary>
    public string Value { get; init; } = Value ?? throw new ArgumentNullException(nameof(Value));

    /// <inheritdoc />
    public override void Validate()
    {
      if (Value is string value && value.Length < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(Value),
                                              "Value has to be at least 1 character long.");
      }
    }

    /// <summary>The fields, a secret one elided.</summary>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
      builder.Append("Value = ");
      builder.Append(Value is null ? "null" : "***");

      return true;
    }
  }

  /// <summary>Refuses a field outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">A field is outside its stated bounds.</exception>
  public abstract void Validate();

  /// <summary>The alternative <paramref name="section" /> names by its one key, matched without case.</summary>
  /// <param name="section">The section, which has to hold one key.</param>
  /// <returns>The alternative, with the fields its key states.</returns>
  /// <exception cref="InvalidOperationException">
  ///   The section names no alternative or two, or one with a field it does not admit.
  /// </exception>
  internal static ProxyOptions Bind(IConfigurationSection section)
  {
    var alternative = ChannelOptionsConfiguration.Alternative(section,
                                                              "ProxyOptions");

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "None"))
    {
      ChannelOptionsConfiguration.Chosen(alternative);

      return new None();
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "System"))
    {
      string? username = null;
      string? password = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "Username"))
        {
          username = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Password"))
        {
          password = ChannelOptionsConfiguration.Text(entry);
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "ProxyOptions.System");
        }
      }

      return new System(username,
                        password);
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "Url"))
    {
      string? address = null;
      string? username = null;
      string? password = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "Address"))
        {
          address = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Username"))
        {
          username = ChannelOptionsConfiguration.Text(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "Password"))
        {
          password = ChannelOptionsConfiguration.Text(entry);
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "ProxyOptions.Url");
        }
      }

      return new Url(address ?? throw ChannelOptionsConfiguration.Missing(alternative,
                                                                          "Address"),
                     username,
                     password);
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "UrlWithCredentials"))
    {
      return new UrlWithCredentials(ChannelOptionsConfiguration.Text(alternative));
    }

    throw ChannelOptionsConfiguration.Unknown(alternative,
                                              "ProxyOptions");
  }
}

/// <summary>Writes a <see cref="ProxyOptions" /> as the engine reads one: an object whose one key names the alternative.</summary>
internal sealed class ProxyOptionsJsonConverter : JsonConverter<ProxyOptions>
{
  /// <inheritdoc />
  /// <remarks>Options go to the engine and nothing reads them back, so this reads nothing.</remarks>
  public override ProxyOptions? Read(ref Utf8JsonReader reader,
                                     Type typeToConvert,
                                     JsonSerializerOptions options)
    => throw new NotSupportedException("ProxyOptions is written to the engine, and never read back.");

  /// <inheritdoc />
  public override void Write(Utf8JsonWriter writer,
                             ProxyOptions value,
                             JsonSerializerOptions options)
    => WriteValue(writer,
                  value);

  /// <summary>Writes <paramref name="written" />, as the converter of a choice holding one does too.</summary>
  /// <param name="writer">Where it is written.</param>
  /// <param name="written">The alternative.</param>
  internal static void WriteValue(Utf8JsonWriter writer,
                                  ProxyOptions written)
  {
    writer.WriteStartObject();

    switch (written)
    {
      case ProxyOptions.None:
      {
        writer.WriteBoolean("None",
                            true);
        break;
      }

      case ProxyOptions.System system:
      {
        writer.WriteStartObject("System");

        if (system.Username is string username)
        {
          writer.WriteString("Username",
                             username);
        }

        if (system.Password is string password)
        {
          writer.WriteString("Password",
                             password);
        }

        writer.WriteEndObject();
        break;
      }

      case ProxyOptions.Url url:
      {
        writer.WriteStartObject("Url");
        writer.WriteString("Address",
                           url.Address);

        if (url.Username is string username)
        {
          writer.WriteString("Username",
                             username);
        }

        if (url.Password is string password)
        {
          writer.WriteString("Password",
                             password);
        }

        writer.WriteEndObject();
        break;
      }

      case ProxyOptions.UrlWithCredentials urlWithCredentials:
      {
        writer.WriteString("UrlWithCredentials",
                           urlWithCredentials.Value);
        break;
      }
    }

    writer.WriteEndObject();
  }
}

/// <summary>
///   The HTTP/2 session a channel's calls share: how it checks that the peer is there, and how much
///   it lets the peer send ahead of what is read.
/// </summary>
public sealed class Http2Options
{
  /// <summary>Options nobody has set.</summary>
  public Http2Options()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public Http2Options(Http2Options other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    KeepAliveIntervalSeconds = other.KeepAliveIntervalSeconds;
    KeepAliveTimeoutSeconds = other.KeepAliveTimeoutSeconds;
    KeepAliveWhileIdle = other.KeepAliveWhileIdle;
    IdleTimeoutSeconds = other.IdleTimeoutSeconds;
    SimultaneousCallsPerConnection = other.SimultaneousCallsPerConnection;
    Send = other.Send is null
             ? null
             : new Http2SendOptions(other.Send);
    Receive = other.Receive;
  }

  /// <summary>How often a PING is sent to the peer. Defaults to none sent.</summary>
  [JsonPropertyName("KeepAliveIntervalSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? KeepAliveIntervalSeconds { get; set; }

  /// <summary>How long a PING may go unanswered before the session and its calls are ended.</summary>
  /// <remarks>Defaults to 20.</remarks>
  [JsonPropertyName("KeepAliveTimeoutSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? KeepAliveTimeoutSeconds { get; set; }

  /// <summary>Whether a PING is also sent while no call is open.</summary>
  /// <remarks>Defaults to false.</remarks>
  [JsonPropertyName("KeepAliveWhileIdle")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public bool? KeepAliveWhileIdle { get; set; }

  /// <summary>
  ///   How long a connection stays open with no call on it before it is closed, the next call
  ///   dialling a new one. Each connection has its own. A call holds its connection to the end of
  ///   its response and of its request.
  /// </summary>
  /// <remarks>Defaults to none: an idle connection stays open.</remarks>
  [JsonPropertyName("IdleTimeoutSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? IdleTimeoutSeconds { get; set; }

  /// <summary>
  ///   How many calls one connection carries at once, never more than its server allows. A call
  ///   that finds every connection full opens another, as many as the calls in flight need, and
  ///   each closes on its own idle timeout when IdleTimeoutSeconds is set. At 1, calls follow one
  ///   another on a connection but never share it, so that a GOAWAY a server sends because of one
  ///   call - nginx's ENHANCE_YOUR_CALM against too many resets, for one - ends that call alone.
  /// </summary>
  /// <remarks>Defaults to none: a connection carries as many calls as its server allows.</remarks>
  [JsonPropertyName("SimultaneousCallsPerConnection")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? SimultaneousCallsPerConnection { get; set; }

  /// <summary>What the session sends.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Send")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public Http2SendOptions? Send { get; set; }

  /// <summary>What the session lets the peer send.</summary>
  /// <remarks>Defaults to <c>{"Fixed": {}}</c>: windows of 2 MiB per call and 5 MiB for the connection.</remarks>
  [JsonPropertyName("Receive")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public Http2ReceiveOptions? Receive { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (KeepAliveIntervalSeconds is double keepAliveIntervalSeconds && (keepAliveIntervalSeconds < 1E-09 || keepAliveIntervalSeconds >= 1.8446744073709552E+19 || double.IsNaN(keepAliveIntervalSeconds) || double.IsInfinity(keepAliveIntervalSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(KeepAliveIntervalSeconds),
                                            keepAliveIntervalSeconds,
                                            "KeepAliveIntervalSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    if (KeepAliveTimeoutSeconds is double keepAliveTimeoutSeconds && (keepAliveTimeoutSeconds < 1E-09 || keepAliveTimeoutSeconds >= 1.8446744073709552E+19 || double.IsNaN(keepAliveTimeoutSeconds) || double.IsInfinity(keepAliveTimeoutSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(KeepAliveTimeoutSeconds),
                                            keepAliveTimeoutSeconds,
                                            "KeepAliveTimeoutSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    if (IdleTimeoutSeconds is double idleTimeoutSeconds && (idleTimeoutSeconds < 1E-09 || idleTimeoutSeconds >= 1.8446744073709552E+19 || double.IsNaN(idleTimeoutSeconds) || double.IsInfinity(idleTimeoutSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(IdleTimeoutSeconds),
                                            idleTimeoutSeconds,
                                            "IdleTimeoutSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    if (SimultaneousCallsPerConnection is int simultaneousCallsPerConnection && simultaneousCallsPerConnection < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(SimultaneousCallsPerConnection),
                                            simultaneousCallsPerConnection,
                                            "SimultaneousCallsPerConnection has to be at least 1.");
    }

    Send?.Validate();
    Receive?.Validate();
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static Http2Options Bind(IConfigurationSection section)
  {
    var bound = new Http2Options();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "KeepAliveIntervalSeconds"))
      {
        bound.KeepAliveIntervalSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "KeepAliveTimeoutSeconds"))
      {
        bound.KeepAliveTimeoutSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "KeepAliveWhileIdle"))
      {
        bound.KeepAliveWhileIdle = ChannelOptionsConfiguration.Boolean(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "IdleTimeoutSeconds"))
      {
        bound.IdleTimeoutSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "SimultaneousCallsPerConnection"))
      {
        bound.SimultaneousCallsPerConnection = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Send"))
      {
        bound.Send = ChannelOptionsConfiguration.Holds(entry) ? Http2SendOptions.Bind(entry) : null;
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Receive"))
      {
        bound.Receive = ChannelOptionsConfiguration.Holds(entry) ? Http2ReceiveOptions.Bind(entry) : null;
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "Http2Options");
      }
    }

    return bound;
  }
}

/// <summary>What an HTTP/2 session sends.</summary>
public sealed class Http2SendOptions
{
  /// <summary>Options nobody has set.</summary>
  public Http2SendOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public Http2SendOptions(Http2SendOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    CoalescingBytes = other.CoalescingBytes;
    StreamBufferSize = other.StreamBufferSize;
    FramesPerWrite = other.FramesPerWrite;
  }

  /// <summary>
  ///   How many bytes a write to the connection may gather before it goes. A write waits while
  ///   the work already ready adds frames to it, one round of the runtime at a time, and goes once
  ///   a round adds none or it holds this many bytes: a request's message handed over while its
  ///   headers wait then goes out with them, in one write rather than two. 0 writes at once.
  /// </summary>
  /// <remarks>Defaults to 16384, 16 KiB.</remarks>
  [JsonPropertyName("CoalescingBytes")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? CoalescingBytes { get; set; }

  /// <summary>
  ///   How many bytes of one call's request may be queued in the session, waiting to be written,
  ///   before its next part is handed over. A part is handed over whole once fewer bytes than this
  ///   are queued, and the peer's window has room, so up to one part more than this is queued.
  /// </summary>
  /// <remarks>Defaults to 1048576, 1 MiB.</remarks>
  [JsonPropertyName("StreamBufferSize")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? StreamBufferSize { get; set; }

  /// <summary>
  ///   How many DATA frames of the peer's largest size one queued part of a request may span,
  ///   written one after the other in one write: a large message then goes out in fewer, larger
  ///   writes. Above 1, a call reset while its part is being written can still send up to this
  ///   many frames less one before its reset, and a PING or a SETTINGS acknowledgement queued
  ///   behind DATA waits for this many times more of it. Above 1 needs an engine built against
  ///   the h2-batch patch (<c>packages/rust/patches/h2-batch</c>), and is refused otherwise. At most
  ///   256.
  /// </summary>
  /// <remarks>Defaults to 1.</remarks>
  [JsonPropertyName("FramesPerWrite")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? FramesPerWrite { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (CoalescingBytes is int coalescingBytes && coalescingBytes < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(CoalescingBytes),
                                            coalescingBytes,
                                            "CoalescingBytes has to be at least 0.");
    }

    if (StreamBufferSize is int streamBufferSize && streamBufferSize < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(StreamBufferSize),
                                            streamBufferSize,
                                            "StreamBufferSize has to be at least 1.");
    }

    if (FramesPerWrite is int framesPerWrite && (framesPerWrite < 1 || framesPerWrite > 256))
    {
      throw new ArgumentOutOfRangeException(nameof(FramesPerWrite),
                                            framesPerWrite,
                                            "FramesPerWrite has to be at least 1 and at most 256.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static Http2SendOptions Bind(IConfigurationSection section)
  {
    var bound = new Http2SendOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "CoalescingBytes"))
      {
        bound.CoalescingBytes = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "StreamBufferSize"))
      {
        bound.StreamBufferSize = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "FramesPerWrite"))
      {
        bound.FramesPerWrite = ChannelOptionsConfiguration.Int32(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "Http2SendOptions");
      }
    }

    return bound;
  }
}

/// <summary>
///   What an HTTP/2 session lets its peer send ahead of what is read: windows of fixed sizes, or
///   windows that grow with what the link carries.
/// </summary>
[JsonConverter(typeof(Http2ReceiveOptionsJsonConverter))]
public abstract record Http2ReceiveOptions
{
  private Http2ReceiveOptions()
  {
  }

  /// <summary>Windows of fixed sizes, announced as the session opens.</summary>
  /// <param name="StreamWindowSize">
  ///   How many bytes of one call the peer may send ahead of what is read.
  ///   Defaults to 2097152, 2 MiB.
  /// </param>
  /// <param name="ConnectionWindowSize">
  ///   How many bytes the peer may send ahead of what is read, across every call of the channel.
  ///   A call its host does not read holds up to <c>StreamWindowSize</c> of it, so enough of them stop
  ///   the others receiving. At least 65535, the window every connection starts with.
  ///   Defaults to 5242880, 5 MiB.
  /// </param>
  public sealed record Fixed(int? StreamWindowSize = null,
                             int? ConnectionWindowSize = null) : Http2ReceiveOptions
  {
    /// <inheritdoc />
    public override void Validate()
    {
      if (StreamWindowSize is int streamWindowSize && streamWindowSize < 1)
      {
        throw new ArgumentOutOfRangeException(nameof(StreamWindowSize),
                                              streamWindowSize,
                                              "StreamWindowSize has to be at least 1.");
      }

      if (ConnectionWindowSize is int connectionWindowSize && connectionWindowSize < 65535)
      {
        throw new ArgumentOutOfRangeException(nameof(ConnectionWindowSize),
                                              connectionWindowSize,
                                              "ConnectionWindowSize has to be at least 65535.");
      }
    }
  }

  /// <summary>
  ///   Windows that grow with the link: both start at 65535, the size every connection starts
  ///   with, and grow with the bandwidth-delay product the session's PINGs measure, up to 16 MiB.
  ///   Neither shrinks.
  /// </summary>
  public sealed record Adaptive : Http2ReceiveOptions
  {
    /// <inheritdoc />
    public override void Validate()
    {
      // The schema bounds nothing here.
    }
  }

  /// <summary>Refuses a field outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">A field is outside its stated bounds.</exception>
  public abstract void Validate();

  /// <summary>The alternative <paramref name="section" /> names by its one key, matched without case.</summary>
  /// <param name="section">The section, which has to hold one key.</param>
  /// <returns>The alternative, with the fields its key states.</returns>
  /// <exception cref="InvalidOperationException">
  ///   The section names no alternative or two, or one with a field it does not admit.
  /// </exception>
  internal static Http2ReceiveOptions Bind(IConfigurationSection section)
  {
    var alternative = ChannelOptionsConfiguration.Alternative(section,
                                                              "Http2ReceiveOptions");

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "Fixed"))
    {
      int? streamWindowSize = null;
      int? connectionWindowSize = null;

      foreach (var entry in ChannelOptionsConfiguration.Entries(alternative))
      {
        if (ChannelOptionsConfiguration.Is(entry,
                                           "StreamWindowSize"))
        {
          streamWindowSize = ChannelOptionsConfiguration.Int32(entry);
        }
        else if (ChannelOptionsConfiguration.Is(entry,
                                                "ConnectionWindowSize"))
        {
          connectionWindowSize = ChannelOptionsConfiguration.Int32(entry);
        }
        else
        {
          throw ChannelOptionsConfiguration.Unknown(entry,
                                                    "Http2ReceiveOptions.Fixed");
        }
      }

      return new Fixed(streamWindowSize,
                       connectionWindowSize);
    }

    if (ChannelOptionsConfiguration.Is(alternative,
                                       "Adaptive"))
    {
      ChannelOptionsConfiguration.Chosen(alternative);

      return new Adaptive();
    }

    throw ChannelOptionsConfiguration.Unknown(alternative,
                                              "Http2ReceiveOptions");
  }
}

/// <summary>Writes a <see cref="Http2ReceiveOptions" /> as the engine reads one: an object whose one key names the alternative.</summary>
internal sealed class Http2ReceiveOptionsJsonConverter : JsonConverter<Http2ReceiveOptions>
{
  /// <inheritdoc />
  /// <remarks>Options go to the engine and nothing reads them back, so this reads nothing.</remarks>
  public override Http2ReceiveOptions? Read(ref Utf8JsonReader reader,
                                            Type typeToConvert,
                                            JsonSerializerOptions options)
    => throw new NotSupportedException("Http2ReceiveOptions is written to the engine, and never read back.");

  /// <inheritdoc />
  public override void Write(Utf8JsonWriter writer,
                             Http2ReceiveOptions value,
                             JsonSerializerOptions options)
    => WriteValue(writer,
                  value);

  /// <summary>Writes <paramref name="written" />, as the converter of a choice holding one does too.</summary>
  /// <param name="writer">Where it is written.</param>
  /// <param name="written">The alternative.</param>
  internal static void WriteValue(Utf8JsonWriter writer,
                                  Http2ReceiveOptions written)
  {
    writer.WriteStartObject();

    switch (written)
    {
      case Http2ReceiveOptions.Fixed @fixed:
      {
        writer.WriteStartObject("Fixed");

        if (@fixed.StreamWindowSize is int streamWindowSize)
        {
          writer.WriteNumber("StreamWindowSize",
                             streamWindowSize);
        }

        if (@fixed.ConnectionWindowSize is int connectionWindowSize)
        {
          writer.WriteNumber("ConnectionWindowSize",
                             connectionWindowSize);
        }

        writer.WriteEndObject();
        break;
      }

      case Http2ReceiveOptions.Adaptive:
      {
        writer.WriteBoolean("Adaptive",
                            true);
        break;
      }
    }

    writer.WriteEndObject();
  }
}

/// <summary>
///   What the channel's calls do: their messages, deadlines and retries, and what crosses between
///   the host and the engine.
/// </summary>
public sealed class GrpcOptions
{
  /// <summary>Options nobody has set.</summary>
  public GrpcOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public GrpcOptions(GrpcOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    UserAgent = other.UserAgent;
    DefaultDeadlineSeconds = other.DefaultDeadlineSeconds;
    Retry = other.Retry is null
              ? null
              : new RetryOptions(other.Retry);
    Send = other.Send is null
             ? null
             : new GrpcSendOptions(other.Send);
    Receive = other.Receive is null
                ? null
                : new GrpcReceiveOptions(other.Receive);
    Host = other.Host is null
             ? null
             : new HostOptions(other.Host);
  }

  /// <summary>What this client calls itself in <c>user-agent</c>.</summary>
  /// <remarks>Defaults to <c>armonik-transport/</c> followed by the engine's version.</remarks>
  [JsonPropertyName("UserAgent")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public string? UserAgent { get; set; }

  /// <summary>
  ///   The deadline of a call that states none, counted from its start: the call ends
  ///   <c>DEADLINE_EXCEEDED</c> once it passes, and the server is told what was left of it when the
  ///   call started as <c>grpc-timeout</c>. A call's own deadline takes its place, and a call that
  ///   states none takes this one.
  /// </summary>
  /// <remarks>
  ///   Defaults to none, a call waiting as long as its answer takes; at least a nanosecond, the
  ///   finest duration the engine holds.
  /// </remarks>
  [JsonPropertyName("DefaultDeadlineSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? DefaultDeadlineSeconds { get; set; }

  /// <summary>When a failed call is sent again.</summary>
  /// <remarks>
  ///   Defaults to <c>{}</c>: five attempts in all, as <c>GrpcClient</c> has them. A call its peer never
  ///   processed goes again besides, whatever <c>MaxAttempts</c> is, while every message it sent is
  ///   kept.
  /// </remarks>
  [JsonPropertyName("Retry")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public RetryOptions? Retry { get; set; }

  /// <summary>What a call sends to the server.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Send")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public GrpcSendOptions? Send { get; set; }

  /// <summary>What a call accepts from the server.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Receive")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public GrpcReceiveOptions? Receive { get; set; }

  /// <summary>What crosses between the host and the engine on each call.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Host")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public HostOptions? Host { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (UserAgent is string userAgent && userAgent.Length < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(UserAgent),
                                            userAgent,
                                            "UserAgent has to be at least 1 character long.");
    }

    if (DefaultDeadlineSeconds is double defaultDeadlineSeconds && (defaultDeadlineSeconds < 1E-09 || defaultDeadlineSeconds >= 1.8446744073709552E+19 || double.IsNaN(defaultDeadlineSeconds) || double.IsInfinity(defaultDeadlineSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(DefaultDeadlineSeconds),
                                            defaultDeadlineSeconds,
                                            "DefaultDeadlineSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    Retry?.Validate();
    Send?.Validate();
    Receive?.Validate();
    Host?.Validate();
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static GrpcOptions Bind(IConfigurationSection section)
  {
    var bound = new GrpcOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "UserAgent"))
      {
        bound.UserAgent = ChannelOptionsConfiguration.Text(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "DefaultDeadlineSeconds"))
      {
        bound.DefaultDeadlineSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Retry"))
      {
        bound.Retry = ChannelOptionsConfiguration.Holds(entry) ? RetryOptions.Bind(entry) : null;
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Send"))
      {
        bound.Send = ChannelOptionsConfiguration.Holds(entry) ? GrpcSendOptions.Bind(entry) : null;
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Receive"))
      {
        bound.Receive = ChannelOptionsConfiguration.Holds(entry) ? GrpcReceiveOptions.Bind(entry) : null;
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Host"))
      {
        bound.Host = ChannelOptionsConfiguration.Holds(entry) ? HostOptions.Bind(entry) : null;
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "GrpcOptions");
      }
    }

    return bound;
  }
}

/// <summary>
///   When a failed call is sent again, as gRFC A6 has it: after a backoff drawn below a bound
///   that starts at <c>InitialBackoffSeconds</c> and grows by <c>BackoffMultiplier</c> to
///   <c>MaxBackoffSeconds</c>, for UNAVAILABLE, ABORTED and UNKNOWN, while no response head has reached
///   the reader and what the call sent is still kept for the replay.
/// </summary>
public sealed class RetryOptions
{
  /// <summary>Options nobody has set.</summary>
  public RetryOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public RetryOptions(RetryOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    MaxAttempts = other.MaxAttempts;
    InitialBackoffSeconds = other.InitialBackoffSeconds;
    MaxBackoffSeconds = other.MaxBackoffSeconds;
    BackoffMultiplier = other.BackoffMultiplier;
    CallReplayBytes = other.CallReplayBytes;
    ChannelReplayBytes = other.ChannelReplayBytes;
  }

  /// <summary>
  ///   Attempts in all, the first included; 1 retries nothing. A call its peer never processed
  ///   goes again besides, whatever this is, while every message it sent is kept.
  /// </summary>
  /// <remarks>Defaults to 5.</remarks>
  [JsonPropertyName("MaxAttempts")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? MaxAttempts { get; set; }

  /// <summary>The bound of the first backoff.</summary>
  /// <remarks>Defaults to 1.</remarks>
  [JsonPropertyName("InitialBackoffSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? InitialBackoffSeconds { get; set; }

  /// <summary>What the bound grows to and no further; refused below <c>InitialBackoffSeconds</c>.</summary>
  /// <remarks>Defaults to 5.</remarks>
  [JsonPropertyName("MaxBackoffSeconds")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? MaxBackoffSeconds { get; set; }

  /// <summary>What each bound is multiplied by; 1 retries at a fixed bound.</summary>
  /// <remarks>Defaults to 1.5.</remarks>
  [JsonPropertyName("BackoffMultiplier")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public double? BackoffMultiplier { get; set; }

  /// <summary>The bytes one call may keep for a replay; a call that sends more is not tried again.</summary>
  /// <remarks>Defaults to 1048576, 1 MiB.</remarks>
  [JsonPropertyName("CallReplayBytes")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? CallReplayBytes { get; set; }

  /// <summary>
  ///   The bytes all of the channel's calls may keep for a replay together; a call whose message
  ///   would pass it is not tried again.
  /// </summary>
  /// <remarks>Defaults to 16777216, 16 MiB.</remarks>
  [JsonPropertyName("ChannelReplayBytes")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? ChannelReplayBytes { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (MaxAttempts is int maxAttempts && maxAttempts < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(MaxAttempts),
                                            maxAttempts,
                                            "MaxAttempts has to be at least 1.");
    }

    if (InitialBackoffSeconds is double initialBackoffSeconds && (initialBackoffSeconds < 1E-09 || initialBackoffSeconds >= 1.8446744073709552E+19 || double.IsNaN(initialBackoffSeconds) || double.IsInfinity(initialBackoffSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(InitialBackoffSeconds),
                                            initialBackoffSeconds,
                                            "InitialBackoffSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    if (MaxBackoffSeconds is double maxBackoffSeconds && (maxBackoffSeconds < 1E-09 || maxBackoffSeconds >= 1.8446744073709552E+19 || double.IsNaN(maxBackoffSeconds) || double.IsInfinity(maxBackoffSeconds)))
    {
      throw new ArgumentOutOfRangeException(nameof(MaxBackoffSeconds),
                                            maxBackoffSeconds,
                                            "MaxBackoffSeconds has to be at least 1E-09 and less than 1.8446744073709552E+19 and finite.");
    }

    if (BackoffMultiplier is double backoffMultiplier && (backoffMultiplier < 1 || double.IsNaN(backoffMultiplier) || double.IsInfinity(backoffMultiplier)))
    {
      throw new ArgumentOutOfRangeException(nameof(BackoffMultiplier),
                                            backoffMultiplier,
                                            "BackoffMultiplier has to be at least 1 and finite.");
    }

    if (CallReplayBytes is int callReplayBytes && callReplayBytes < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(CallReplayBytes),
                                            callReplayBytes,
                                            "CallReplayBytes has to be at least 0.");
    }

    if (ChannelReplayBytes is int channelReplayBytes && channelReplayBytes < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(ChannelReplayBytes),
                                            channelReplayBytes,
                                            "ChannelReplayBytes has to be at least 0.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static RetryOptions Bind(IConfigurationSection section)
  {
    var bound = new RetryOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "MaxAttempts"))
      {
        bound.MaxAttempts = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "InitialBackoffSeconds"))
      {
        bound.InitialBackoffSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "MaxBackoffSeconds"))
      {
        bound.MaxBackoffSeconds = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "BackoffMultiplier"))
      {
        bound.BackoffMultiplier = ChannelOptionsConfiguration.Double(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "CallReplayBytes"))
      {
        bound.CallReplayBytes = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "ChannelReplayBytes"))
      {
        bound.ChannelReplayBytes = ChannelOptionsConfiguration.Int32(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "RetryOptions");
      }
    }

    return bound;
  }
}

/// <summary>What a call sends to the server.</summary>
public sealed class GrpcSendOptions
{
  /// <summary>Options nobody has set.</summary>
  public GrpcSendOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public GrpcSendOptions(GrpcSendOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    MaxMessageSize = other.MaxMessageSize;
    Compression = other.Compression;
  }

  /// <summary>
  ///   The largest message this client will send, in bytes. A larger one ends its call
  ///   <c>RESOURCE_EXHAUSTED</c>, and none of it is sent.
  /// </summary>
  /// <remarks>
  ///   Defaults to none, any message a call is given going out. Zero is refused: it admits only
  ///   empty messages.
  /// </remarks>
  [JsonPropertyName("MaxMessageSize")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? MaxMessageSize { get; set; }

  /// <summary>
  ///   The encoding the messages of a call are compressed with, which the call states as
  ///   <c>grpc-encoding</c>. A message that would not be smaller compressed is sent as it is, and
  ///   <c>MaxMessageSize</c> is checked on a message before it is compressed.
  /// </summary>
  /// <remarks>
  ///   The server has to accept the encoding: one that does not ends the call <c>UNIMPLEMENTED</c>,
  ///   and there is no fallback to sending the messages as they are.
  ///   Defaults to none, the messages going out as they are.
  /// </remarks>
  [JsonPropertyName("Compression")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public MessageEncoding? Compression { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (MaxMessageSize is int maxMessageSize && maxMessageSize < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(MaxMessageSize),
                                            maxMessageSize,
                                            "MaxMessageSize has to be at least 1.");
    }

    if (Compression is MessageEncoding compression && !Enum.IsDefined(typeof(MessageEncoding), compression))
    {
      throw new ArgumentOutOfRangeException(nameof(Compression),
                                            compression,
                                            "Compression has to be a name MessageEncoding declares.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static GrpcSendOptions Bind(IConfigurationSection section)
  {
    var bound = new GrpcSendOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "MaxMessageSize"))
      {
        bound.MaxMessageSize = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Compression"))
      {
        bound.Compression = ChannelOptionsConfiguration.Enumeration<MessageEncoding>(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "GrpcSendOptions");
      }
    }

    return bound;
  }
}

/// <summary>How the messages of a call are compressed.</summary>
[JsonConverter(typeof(JsonStringEnumConverter<MessageEncoding>))]
public enum MessageEncoding
{
  /// <summary>RFC 1952 gzip.</summary>
  Gzip,
}

/// <summary>What a call accepts from the server.</summary>
public sealed class GrpcReceiveOptions
{
  /// <summary>Options nobody has set.</summary>
  public GrpcReceiveOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public GrpcReceiveOptions(GrpcReceiveOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    MaxMessageSize = other.MaxMessageSize;
    Compression = other.Compression;
  }

  /// <summary>The largest message this client will accept, in bytes.</summary>
  /// <remarks>
  ///   Defaults to 4194304, 4 MiB. No upper bound, because the largest a caller can name is a
  ///   channel that refuses nothing. Zero is refused: it is a channel that can receive no message
  ///   at all.
  /// </remarks>
  [JsonPropertyName("MaxMessageSize")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? MaxMessageSize { get; set; }

  /// <summary>
  ///   The encoding besides <c>identity</c> that this client accepts for the messages of an answer,
  ///   which it states as <c>grpc-accept-encoding</c>. A server may then compress what it sends, and
  ///   <c>MaxMessageSize</c> bounds a message once it is decompressed. A message compressed in any other
  ///   encoding ends its call <c>INTERNAL</c>.
  /// </summary>
  /// <remarks>Defaults to none, only <c>identity</c> being accepted.</remarks>
  [JsonPropertyName("Compression")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public MessageEncoding? Compression { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (MaxMessageSize is int maxMessageSize && maxMessageSize < 1)
    {
      throw new ArgumentOutOfRangeException(nameof(MaxMessageSize),
                                            maxMessageSize,
                                            "MaxMessageSize has to be at least 1.");
    }

    if (Compression is MessageEncoding compression && !Enum.IsDefined(typeof(MessageEncoding), compression))
    {
      throw new ArgumentOutOfRangeException(nameof(Compression),
                                            compression,
                                            "Compression has to be a name MessageEncoding declares.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static GrpcReceiveOptions Bind(IConfigurationSection section)
  {
    var bound = new GrpcReceiveOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "MaxMessageSize"))
      {
        bound.MaxMessageSize = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Compression"))
      {
        bound.Compression = ChannelOptionsConfiguration.Enumeration<MessageEncoding>(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "GrpcReceiveOptions");
      }
    }

    return bound;
  }
}

/// <summary>What crosses between the host and the engine on each call, one way and the other.</summary>
public sealed class HostOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostOptions(HostOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Send = other.Send is null
             ? null
             : new HostSendOptions(other.Send);
    Receive = other.Receive is null
                ? null
                : new HostReceiveOptions(other.Receive);
  }

  /// <summary>What the host sends.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Send")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public HostSendOptions? Send { get; set; }

  /// <summary>What the engine delivers to the host.</summary>
  /// <remarks>Defaults to <c>{}</c>, which leaves each of its options at its own default.</remarks>
  [JsonPropertyName("Receive")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public HostReceiveOptions? Receive { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    Send?.Validate();
    Receive?.Validate();
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static HostOptions Bind(IConfigurationSection section)
  {
    var bound = new HostOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "Send"))
      {
        bound.Send = ChannelOptionsConfiguration.Holds(entry) ? HostSendOptions.Bind(entry) : null;
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "Receive"))
      {
        bound.Receive = ChannelOptionsConfiguration.Holds(entry) ? HostReceiveOptions.Bind(entry) : null;
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "HostOptions");
      }
    }

    return bound;
  }
}

/// <summary>What a call's host sends: the messages it hands the engine.</summary>
public sealed class HostSendOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostSendOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostSendOptions(HostSendOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Window = other.Window;
  }

  /// <summary>How many messages a call may have sent and unacquitted at once.</summary>
  /// <remarks>Defaults to 1.</remarks>
  [JsonPropertyName("Window")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Window { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (Window is int window && (window < 1 || window > 536870910))
    {
      throw new ArgumentOutOfRangeException(nameof(Window),
                                            window,
                                            "Window has to be at least 1 and at most 536870910.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static HostSendOptions Bind(IConfigurationSection section)
  {
    var bound = new HostSendOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "Window"))
      {
        bound.Window = ChannelOptionsConfiguration.Int32(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "HostSendOptions");
      }
    }

    return bound;
  }
}

/// <summary>What the engine delivers to a call's host: its payloads and its status.</summary>
public sealed class HostReceiveOptions
{
  /// <summary>Options nobody has set.</summary>
  public HostReceiveOptions()
  {
  }

  /// <summary>A copy of <paramref name="other" />, sharing nothing with it.</summary>
  /// <param name="other">The options to copy.</param>
  /// <exception cref="ArgumentNullException"><paramref name="other" /> is null.</exception>
  public HostReceiveOptions(HostReceiveOptions other)
  {
    if (other is null)
    {
      throw new ArgumentNullException(nameof(other));
    }

    Window = other.Window;
    CoalescingBytes = other.CoalescingBytes;
  }

  /// <summary>
  ///   How many of a call's payloads the host may hold at once, delivered and not yet given back.
  ///   The terminal status takes none, so a host holds at most one more.
  /// </summary>
  /// <remarks>Defaults to 4.</remarks>
  [JsonPropertyName("Window")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? Window { get; set; }

  /// <summary>
  ///   How many bytes of a response a delivery to the host may wait to gather, so that a unary
  ///   answer's head, message and status reach it in one callback. 0 delivers each read at once.
  /// </summary>
  /// <remarks>Defaults to 16384, 16 KiB.</remarks>
  [JsonPropertyName("CoalescingBytes")]
  [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
  public int? CoalescingBytes { get; set; }

  /// <summary>Refuses an option outside the range the engine accepts.</summary>
  /// <exception cref="ArgumentOutOfRangeException">An option is outside its stated bounds.</exception>
  public void Validate()
  {
    if (Window is int window && (window < 1 || window > 536870910))
    {
      throw new ArgumentOutOfRangeException(nameof(Window),
                                            window,
                                            "Window has to be at least 1 and at most 536870910.");
    }

    if (CoalescingBytes is int coalescingBytes && coalescingBytes < 0)
    {
      throw new ArgumentOutOfRangeException(nameof(CoalescingBytes),
                                            coalescingBytes,
                                            "CoalescingBytes has to be at least 0.");
    }
  }

  /// <summary>The options <paramref name="section" /> states, each key matched to one without case.</summary>
  /// <param name="section">The section, whose every key has to name an option.</param>
  /// <returns>The options, unset where the section states nothing.</returns>
  /// <exception cref="InvalidOperationException">A key names no option, or holds what its option does not admit.</exception>
  internal static HostReceiveOptions Bind(IConfigurationSection section)
  {
    var bound = new HostReceiveOptions();

    foreach (var entry in ChannelOptionsConfiguration.Entries(section))
    {
      if (ChannelOptionsConfiguration.Is(entry,
                                         "Window"))
      {
        bound.Window = ChannelOptionsConfiguration.Int32(entry);
      }
      else if (ChannelOptionsConfiguration.Is(entry,
                                              "CoalescingBytes"))
      {
        bound.CoalescingBytes = ChannelOptionsConfiguration.Int32(entry);
      }
      else
      {
        throw ChannelOptionsConfiguration.Unknown(entry,
                                                  "HostReceiveOptions");
      }
    }

    return bound;
  }
}

/// <summary>How the text of a configuration becomes the options above, and why it may not.</summary>
internal static class ChannelOptionsConfiguration
{
  /// <summary>Whether <paramref name="section" /> is the key <paramref name="name" />, without case.</summary>
  internal static bool Is(IConfigurationSection section,
                          string                name)
    => string.Equals(section.Key,
                     name,
                     StringComparison.OrdinalIgnoreCase);

  /// <summary>The keys of a section that holds options, a key set to null left out as unset.</summary>
  /// <exception cref="InvalidOperationException">It holds a value instead.</exception>
  internal static IConfigurationSection[] Entries(IConfigurationSection section)
    => string.IsNullOrEmpty(section.Value)
         ? section.GetChildren()
                  .Where(entry => entry.Value is not null || entry.GetChildren()
                                                                  .Any())
                  .ToArray()
         : throw new InvalidOperationException($"{section.Path} holds a value, and it names options.");

  /// <summary>Whether a key names anything, an empty one leaving its group or choice unset.</summary>
  internal static bool Holds(IConfigurationSection section)
    => !string.IsNullOrEmpty(section.Value) || section.GetChildren()
                                                      .Any();

  /// <summary>The one key of a section naming an alternative of <paramref name="choice" />.</summary>
  /// <exception cref="InvalidOperationException">It holds none, or more than one.</exception>
  internal static IConfigurationSection Alternative(IConfigurationSection section,
                                                    string                choice)
  {
    var entries = Entries(section);

    return entries.Length == 1
             ? entries[0]
             : throw new InvalidOperationException($"{section.Path} names {entries.Length} alternatives of {choice}, and it has to name one.");
  }

  /// <summary>Refuses an alternative chosen with anything but `true`.</summary>
  internal static void Chosen(IConfigurationSection section)
  {
    if (Boolean(section) != true)
    {
      throw new InvalidOperationException($"{section.Path} has to be true: an alternative is chosen with true.");
    }
  }

  /// <summary>The text of a key that holds a value.</summary>
  /// <exception cref="InvalidOperationException">It holds options instead.</exception>
  internal static string Text(IConfigurationSection section)
    => section.Value ?? throw new InvalidOperationException($"{section.Path} holds options, and it names a value.");

  /// <summary>An integer, or none where the text is empty.</summary>
  internal static int? Int32(IConfigurationSection section)
  {
    var text = Text(section);

    return text.Length == 0
             ? null
             : int.TryParse(text,
                            NumberStyles.Integer,
                            CultureInfo.InvariantCulture,
                            out var value)
               ? value
               : throw Unreadable(section,
                                  "an integer");
  }

  /// <summary>A number, or none where the text is empty.</summary>
  internal static double? Double(IConfigurationSection section)
  {
    var text = Text(section);

    return text.Length == 0
             ? null
             : double.TryParse(text,
                               NumberStyles.Float,
                               CultureInfo.InvariantCulture,
                               out var value)
               ? value
               : throw Unreadable(section,
                                  "a number");
  }

  /// <summary>A flag, or none where the text is empty.</summary>
  internal static bool? Boolean(IConfigurationSection section)
  {
    var text = Text(section);

    return text.Length == 0
             ? null
             : bool.TryParse(text,
                             out var value)
               ? value
               : throw Unreadable(section,
                                  "true or false");
  }

  /// <summary>A name <typeparamref name="T" /> declares, without case, or none where the text is empty.</summary>
  /// <remarks>Matched by name, never parsed: `Enum.TryParse` reads digits as any value of the type.</remarks>
  internal static T? Enumeration<T>(IConfigurationSection section)
    where T : struct, Enum
  {
    var text = Text(section);

    if (text.Length == 0)
    {
      return null;
    }

    var names = Enum.GetNames(typeof(T));
    var name = names.FirstOrDefault(declared => string.Equals(declared,
                                                              text,
                                                              StringComparison.OrdinalIgnoreCase));

    return name is null
             ? throw Unreadable(section,
                                "one of " + string.Join(", ",
                                                        names))
             : (T)Enum.Parse(typeof(T),
                             name);
  }

  /// <summary>A key nothing declares, refused by its path.</summary>
  internal static InvalidOperationException Unknown(IConfigurationSection section,
                                                    string                owner)
    => new($"{section.Path} names nothing {owner} declares.");

  /// <summary>A field the alternative cannot be made without.</summary>
  internal static InvalidOperationException Missing(IConfigurationSection section,
                                                    string                what)
    => new($"{section.Path} has to state {what}.");

  private static InvalidOperationException Unreadable(IConfigurationSection section,
                                                      string                what)
    => new($"{section.Path} has to be {what}.");
}
